import SwiftUI
struct SuperAdminDashboardView:View{let user:SessionUser;@StateObject private var vm=SuperAdminDashboardViewModel();var body:some View{List{if let e=vm.errorMessage{Text(e).foregroundStyle(.red)}Section("HTG Businesses") {Text("Businesses: \(vm.admins.count)").font(.headline);ForEach(vm.admins){a in VStack(alignment:.leading,spacing:4){Text(a.business_name).font(.headline);Text("Admin: \(a.username)");Text(a.is_active==1 ? "ACTIVE":"INACTIVE");if let x=a.subscription_expiry{Text("Expiry: \(x)").font(.footnote).foregroundStyle(.secondary)}}.padding(.vertical,4)}}}.overlay{if vm.isLoading{ProgressView()}}.navigationTitle("HTG Super Admin").task{await vm.load(token:user.token)}}